const PAL=['#2d7a55','#c8a24a','#4aa57a','#b3412f','#8fb5a0','#3b5d4c','#d9c08a'],SN=['HR','Ops','Finance','PR','Sales','Logistics','Care','Production','Inventory','BI&A'],ORD='New,Processing,Packed,Dispatched,In transit,Delivered,Cancelled'.split(','),TS=['To do','In progress','Done'];
const cp=n=>n>=1e6?(n/1e6).toFixed(1)+'M':n>=1e4?(n/1e3).toFixed(0)+'k':n>=1e3?(n/1e3).toFixed(1)+'k':String(Math.round(n));
const iso=t=>new Date(t).toISOString().slice(0,10),dN=n=>[...Array(n)].map((_,i)=>iso(Date.now()-(n-1-i)*864e5));
const ser=(k,fn)=>dN(7).map(d=>[d.slice(5),R(k).filter(r=>iso(r.ts)==d&&r.st!='Cancelled').reduce((s,r)=>s+fn(r),0)]);
const actD=(d,n)=>{const cn={},em=d?mem(d).map(u=>u.email):[];Object.keys(DB.rec).forEach(k=>R(k).forEach(r=>{if(!d||r.dept==d)cn[iso(r.ts)]=(cn[iso(r.ts)]||0)+1}));DB.att.forEach(a=>{if(!d||em.includes(a.email))cn[a.d]=(cn[a.d]||0)+1});return dN(n).map(x=>[x.slice(5),cn[x]||0])};
const stc=(k,l)=>l.map(s=>[s,L(k,s).length]),cnt=(k,f)=>R(k).filter(f).length;
const stp=()=>{const m={};R('stk').forEach(r=>m[r.v.prod]=(m[r.v.prod]||0)+(+r.v.qty||0));return Object.entries(m).sort((a,b)=>b[1]-a[1]).slice(0,6)};
const fake=(a,s)=>a.map((x,i)=>[x[0],20+((i*37+s*17)%61)]),prep=(a,s)=>S.demo&&a.every(x=>!x[1])?[fake(a,s),1]:[a,0];
const pan=(t,h,sp)=>`<div class="c pn"><h4>${E(t)}${sp?' <span class="bd" style="background:var(--gold)">Sample</span>':''}</h4>${h}</div>`;
const emp=()=>`<div class="vb gh">${[40,65,30,80,55,70,45].map(x=>`<div><i style="height:${x}%"></i></div>`).join('')}</div><small class="mu">No data yet. This fills in as your team works.</small>`;
const spark=a=>{const m=Math.max(...a.map(x=>x[1]));return m?`<svg class="sp" viewBox="0 0 100 30" preserveAspectRatio="none"><polyline fill="none" stroke="currentColor" stroke-width="2" vector-effect="non-scaling-stroke" points="${a.map((x,i)=>(i*100/(a.length-1)).toFixed(1)+','+(28-x[1]/m*24).toFixed(1)).join(' ')}"/></svg>`:''};
const card=(l,v,s)=>`<div class="c"><small>${E(l)}</small><b>${v}</b>${s?spark(s):''}</div>`;
function donut(t,a,s){let sp;[a,sp]=prep(a,s);const tot=a.reduce((x,y)=>x+y[1],0);if(!tot)return pan(t,emp());let off=0;const cf=2*Math.PI*40;
return pan(t,`<div class="dn"><svg viewBox="0 0 120 120"><circle r="40" cx="60" cy="60" fill="none" stroke="var(--ln)" stroke-width="16"/>${a.map((x,i)=>{const l=x[1]/tot*cf,e=`<circle r="40" cx="60" cy="60" fill="none" stroke="${PAL[i%7]}" stroke-width="16" stroke-dasharray="${l} ${cf-l}" stroke-dashoffset="${-off}" transform="rotate(-90 60 60)"/>`;off+=l;return e}).join('')}<text x="60" y="60" text-anchor="middle" font-size="20" font-weight="700" fill="currentColor">${cp(tot)}</text><text x="60" y="75" text-anchor="middle" font-size="8" fill="#888">total</text></svg><div>${a.map((x,i)=>x[1]?`<div class="lgd"><i style="background:${PAL[i%7]}"></i>${E(x[0])} <b>${x[1].toLocaleString('en-NG')}</b></div>`:'').join('')}</div></div>`,sp)}
function vbars(t,a,s,fmt){let sp;[a,sp]=prep(a,s);const m=Math.max(...a.map(x=>x[1]));if(!m)return pan(t,emp());return pan(t,`<div class="vb">${a.map(x=>`<div title="${E(x[0])}: ${x[1]}"><b>${(fmt||cp)(x[1])}</b><i style="height:${Math.max(3,x[1]/m*100)}%"></i><small>${E(x[0])}</small></div>`).join('')}</div>`,sp)}
let gid=0;
function area(t,a,s,fmt){let sp;[a,sp]=prep(a,s);const m=Math.max(...a.map(x=>x[1]));if(!m)return pan(t,emp());const n=a.length,id='g'+(++gid),l=a.map((x,i)=>(i?'L':'M')+(i*300/(n-1)).toFixed(1)+','+(92-x[1]/m*80).toFixed(1)).join(' ');
return pan(t,`<svg viewBox="0 0 300 100" preserveAspectRatio="none" style="width:100%;height:150px;display:block"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#2d7a55" stop-opacity=".35"/><stop offset="1" stop-color="#2d7a55" stop-opacity="0"/></linearGradient></defs><path d="${l} L300,100 L0,100 Z" fill="url(#${id})"/><path d="${l}" fill="none" stroke="#2d7a55" stroke-width="2.5" vector-effect="non-scaling-stroke"/></svg><div style="display:flex;justify-content:space-between"><small class="mu">${a[0][0]}</small><small class="mu">Peak ${(fmt||cp)(m)}</small><small class="mu">${a[n-1][0]}</small></div>`,sp)}
function heat(t,a,s){let sp;[a,sp]=prep(a,s);const m=Math.max(...a.map(x=>x[1]));if(!m)return pan(t,emp());return pan(t,`<div class="hm">${a.map(x=>`<i title="${x[0]}: ${x[1]}" style="opacity:${(.12+.88*x[1]/m).toFixed(2)}"></i>`).join('')}</div><small class="mu">Last ${a.length} days. Darker means busier.</small>`,sp)}
const rvs=()=>ser('ord',r=>r.v.pay=='Confirmed'?+r.v.tot||0:0),dtd=()=>DEPTS.slice(0,10).map((d,i)=>{const t=DB.tasks.filter(x=>x.dept==d);return[SN[i],t.length?Math.round(t.filter(x=>x.status=='Done').length/t.length*100):0]});
const CH={
FN:()=>[area('Revenue, last 7 days',rvs(),1,N),donut('Where the money goes',[['Expenses',sum('exp','amt')],['Suppliers',sum('spay','amt')],['Payroll',sum('payr','amt',x=>x.st=='Paid')],['Transport',sum('lexp','amt')],['Production',sum('pcost','amt')]],2)],
SL:()=>[area('Sales, last 7 days',ser('ord',r=>+r.v.tot||0),3,N),donut('Orders by status',stc('ord',ORD),4)],
IN:()=>[donut('Stock availability',[['Available',cnt('stk',r=>+r.v.qty>+r.v.low)],['Low stock',cnt('stk',r=>+r.v.qty<=+r.v.low&&+r.v.qty>0)],['Sold out',cnt('stk',r=>+r.v.qty<=0)]],5),vbars('Units by product',stp(),6)],
PD:()=>[donut('Production stages',stc('porder','Requested,Cutting,Stitching,Finishing,Quality check,Completed'.split(',')),7),vbars('Quality inspection',stc('qa','Submitted for inspection,Passed,Failed,Rework'.split(',')),8)],
LG:()=>[donut('Shipments',stc('ord',['Processing','Packed','Dispatched','In transit','Delivered']),9),vbars('Delivery assignments',stc('asg',['Assigned','Dispatched','Delivered']),10)],
OP:()=>[donut('Tasks across departments',TS.map(s=>[s,DB.tasks.filter(t=>t.status==s).length]),11),vbars('Open tasks by department',DEPTS.slice(0,10).map((d,i)=>[SN[i],DB.tasks.filter(t=>t.dept==d&&t.status!='Done').length]),12)],
HR:()=>[donut('Staff by department',DEPTS.slice(0,10).map((d,i)=>[SN[i],mem(d).length]),13),vbars('Leave requests',stc('leave',['Pending','Approved','Rejected']),14)],
CC:()=>[donut('Cases',stc('enq',['Open','Answered','Escalated','Resolved']),15),vbars('Returns, exchanges and refunds',[['Returns',R('retn').length],['Exchanges',R('exch').length],['Refunds',R('ref').length]],16)],
PR:()=>[donut('Website content',[['Banners live',L('ban','Live').length],['Sections live',L('sect','Live').length],['Announcements',L('wann','Live').length],['Drafts',['ban','sect','wann','fcam','vban'].reduce((s,k)=>s+L(k,'Draft').length,0)]],17),vbars('Marketing campaigns',stc('mcamp',['Planned','Running','Ended']),18)],
BI:()=>[area('Revenue, last 7 days',rvs(),19,N),donut('Orders by status',stc('ord',ORD),20)]};
function pend(keys){const out=[];keys.forEach(k=>{const cc=C[k];if(cc&&cc.s&&can(k,'ap')&&cc.ap!==undefined||cc&&cc.s&&cc.s.split(',').length>2&&can(k,'ap')){const f=cc.s.split(',')[0];vis(k).filter(r=>r.st==f).forEach(r=>out.push([k,r]))}});return out}
function ov(d){const code=Object.keys(D).find(x=>D[x]==d),m=(MENU[code]||[]).map(it),ks=[...new Set(m.map(x=>x[0]))].filter(k=>C[k]&&!C[k].ro),ex=(XC[code]||[]).map(x=>card(x[0],x[1](),x[2]&&x[2]())).join(''),open=DB.tasks.filter(t=>t.dept==d&&t.status!='Done').length,pd=pend(ks).slice(0,6);
return `<div class="kp">${card('Active staff',mem(d).length)}${card('Open tasks',open)}${ex}</div><div class="g2">${(CH[code]||(()=>[]))().join('')}</div><div class="g2">${vbars('Activity, last 7 days',actD(d,7),21)}${heat('Activity, last 4 weeks',actD(d,28),22)}</div>${pd.length?`<h3>Needs your attention</h3>${pd.map(p=>`<div class="ms cl" onclick="go('${p[0]}')"><span class="bd">${E(C[p[0]].t)}</span> ${E(Object.values(p[1].v)[0])} · ${E(p[1].st)}</div>`).join('')}`:''}<h3>${E(d)} tools</h3><div class="dg">${m.map(x=>`<div class="c cl" onclick="go('${x[0]}')"><b>${E(x[1])}</b>${C[x[0]]&&!C[x[0]].ro?`<br><small>${R(x[0]).length} records</small>`:''}</div>`).join('')}</div>`}
const pendAll=()=>pend(Object.keys(C));
const V={};
V.dash=()=>{const u=S.me,hr=new Date().getHours(),g=hr<12?'morning':hr<17?'afternoon':'evening',
hero=`<div class="hero"><div><h2>Good ${g}, ${E(nm(u).split('@')[0])}</h2><p>${E(u.pos)} · ${E(u.dept)} · ${u.id}</p></div><button class="sm" style="background:#ffffff33;padding:8px 14px" onclick="S.demo=!S.demo;render()">${S.demo?'Hide':'Preview'} sample data</button></div>`;
if(!isEx(u))return hero+ov(u.dept);
return hero+`<div class="kp">${card('Active staff',DB.users.filter(x=>x.status=='Active').length)}${card('Orders',R('ord').length,ser('ord',()=>1))}${card('Revenue (confirmed)',N(rev()),rvs())}${card('Awaiting approval',pendAll().length)}</div><div class="g2">${area('Revenue, last 7 days',rvs(),1,N)}${donut('Staff by department',DEPTS.slice(0,10).map((d,i)=>[SN[i],mem(d).length]),13)}</div><div class="g2">${vbars('Tasks completed %',dtd(),23)}${heat('Company activity, last 4 weeks',actD(null,28),22)}</div>${V.alld()}<h3>Recent activity</h3>${DB.log.slice(0,8).map(l=>`<div class="ms">${E(l.t)} <small class="mu">${fm(l.ts)}</small></div>`).join('')||'<p class="mu">Nothing yet.</p>'}`};
V.alld=()=>`<h2>All Departments</h2><p class="mu">${isEx(S.me)?'Full access to every department.':'View access to every department.'}</p><div class="dg">${DEPTS.slice(0,10).map((d,i)=>`<div class="c cl" onclick="go('dept',${i})"><b>${E(d)}</b><br><small>${mem(d).length} staff · ${DB.tasks.filter(t=>t.dept==d&&t.status!='Done').length} open tasks</small></div>`).join('')}</div>`;
V.dept=i=>{const d=DEPTS[i];return `<h2>${E(d)}</h2>${ov(d)}<h3>Staff</h3><div class="tw"><table>${DB.users.filter(u=>u.dept==d).map(u=>`<tr><td>${u.id}</td><td>${E(nm(u))}</td><td>${E(u.pos)}</td><td>${u.status}</td></tr>`).join('')||'<tr><td>No staff yet</td></tr>'}</table></div>`};
V.appr=()=>{const p=pendAll();return `<h2>Approvals</h2><p class="mu">Everything waiting across departments.</p>${p.map(x=>`<div class="ms cl" onclick="go('${x[0]}')"><span class="bd">${E(C[x[0]].t)}</span> ${E(Object.values(x[1].v)[0])} · ${E(x[1].st)} · ${E(x[1].by)}</div>`).join('')||'<p class="mu">Nothing waiting.</p>'}`};
V.fin=()=>{const r=rev(),co=cost();return `<h2>Financial Statements</h2><div class="kp">${card('Revenue (confirmed payments)',N(r),rvs())}${card('Total costs',N(co))}${card('Profit / loss',N(r-co))}${card('Pending payment checks',L('pay','Pending').length)}</div><div class="g2">${vbars('Revenue, costs and profit',[['Revenue',r],['Costs',co],['Profit',Math.max(0,r-co)]],1,N)}${donut('Where the money goes',[['Expenses',sum('exp','amt')],['Suppliers',sum('spay','amt')],['Payroll',sum('payr','amt',x=>x.st=='Paid')],['Transport',sum('lexp','amt')],['Production',sum('pcost','amt')]],2)}</div><h3>Outstanding</h3><div class="ms">Unconfirmed orders value: ${N(sum('ord','tot',x=>x.v.pay!='Confirmed'&&x.st!='Cancelled'))}</div><div class="ms">Refund requests awaiting approval: ${L('ref','Recommended').length}</div>`};
V.bi=()=>{const rv=rvs(),av=rv.reduce((s,x)=>s+x[1],0)/7,n=R('ord').length;
return `<h2>Analytics Dashboard</h2><div class="bt"><button onclick="S.demo=!S.demo;render()">${S.demo?'Hide':'Preview'} sample data</button></div><div class="kp">${card('Orders',n,ser('ord',()=>1))}${card('Revenue (confirmed)',N(rev()),rv)}${card('Average order',N(n?sum('ord','tot')/n:0))}${card('30-day forecast',N(av*30))}</div><div class="g2">${area('Sales, last 7 days',ser('ord',r=>+r.v.tot||0),3,N)}${donut('Orders by status',stc('ord',ORD),4)}</div><div class="g2">${vbars('Departmental performance (tasks done %)',dtd(),23)}${vbars('Attendance today',DEPTS.slice(0,10).map((d,i)=>[SN[i],new Set(DB.att.filter(a=>a.d==T()&&mem(d).some(u=>u.email==a.email)).map(a=>a.email)).size]),24)}</div><div class="g2">${donut('Stock availability',[['Available',cnt('stk',r=>+r.v.qty>+r.v.low)],['Low stock',cnt('stk',r=>+r.v.qty<=+r.v.low&&+r.v.qty>0)],['Sold out',cnt('stk',r=>+r.v.qty<=0)]],5)}${donut('Costs',[['Expenses',sum('exp','amt')],['Suppliers',sum('spay','amt')],['Payroll',sum('payr','amt',x=>x.st=='Paid')],['Transport',sum('lexp','amt')],['Production',sum('pcost','amt')]],2)}</div><div class="g2">${heat('Company activity, last 4 weeks',actD(null,28),22)}${vbars('Alerts',[['Production delays',L('delayp','Reported').length],['Open returns',L('retn','Requested').length],['Pending leave',L('leave','Pending').length],['Open cases',L('enq','Open').length]],25)}</div>${can('brep','w')?`<div class="bt"><button class="pr" onclick="genrep()">Generate report from current data</button></div>`:''}`};
function genrep(){act(()=>api('/api/rec/brep','POST',{v:{title:'Auto report '+T(),period:'Daily',body:`Orders ${R('ord').length}; revenue ${N(rev())}; costs ${N(cost())}; profit ${N(rev()-cost())}; low-stock ${R('stk').filter(x=>+x.v.qty<=+x.v.low).length}; production delays ${L('delayp','Reported').length}; open returns ${L('retn','Requested').length}.`}}),'Report saved under Management Reports')}
V.web=()=>{const x=JSON.stringify(WB,(k,v)=>typeof v=='string'&&v.length>300?'[file]':v,2);return `<h2>Storefront Controls</h2><p class="mu">What departments have published. The storefront will read exactly this once you connect it.</p><div class="kp">${card('Published products',WB.products.length)}${card('Live banners',WB.banners.length)}${card('Top video banner',WB.topVideo?'Live':'None')}${card('Active campaigns',WB.camps.length)}${card('Sold-out products',Object.values(WB.stock).filter(q=>q<=0).length)}</div>${bars([['Approved discounts',Object.keys(WB.disc).length],['Featured picks',WB.featured.length],['Promo sections',WB.sections.length],['Website announcements',WB.ann.length],['FAQs live',WB.faqs.length],['Testimonials',WB.testi.length],['Shipping rules',Object.keys(WB.ship).length],['Delivery fee overrides',Object.keys(WB.fees).length],['Unavailable products',Object.keys(WB.unavail).length],['Payment methods',WB.pay.length],['Account details',WB.bank.length]])}<h3>Flash sale / Black Friday</h3><div class="ms">${WB.flash?'Flash Sale active until '+E(WB.flash.end)+' ('+E(WB.flash.pct)+'% off)':'No active Flash Sale'} · Black Friday ${WB.bf?'ON':'off'}</div><h3>Published data</h3><pre>${E(x)}</pre>`};
V.stock=()=>{const rows=R('stk'),w=can('stk','w');return `<h2>Stock &amp; Availability</h2>${w?`<div class="c"><h3>Add product to stock</h3>${fld(C.stk.f).map(inp).join('')}<div class="bt"><button class="pr" onclick="radd('stk')">Add</button></div></div><label>Quantity for Receive / Issue / Adjust<input id="sq" type="number" value="1" min="0"></label>`:''}<div class="tw"><table><tr><th>Product</th><th>Size</th><th>Colour</th><th>In stock</th><th>Alert at</th><th>Storefront shows</th><th></th></tr>${rows.map(r=>{const q=+r.v.qty,lo=q<=+r.v.low;return `<tr><td>${E(r.v.prod)}</td><td>${E(r.v.size)}</td><td>${E(r.v.colour)}</td><td><b>${q}</b></td><td>${E(r.v.low)}</td><td>${q<=0?'<span class="bd">Sold Out</span>':lo?'<span class="bd" style="background:var(--gold)">Low stock</span>':'<span class="bd g">Available</span>'}</td><td>${w?`<button class="sm" onclick="smv(${r.id},'Received')">Receive</button><button class="sm" onclick="smv(${r.id},'Issued')">Issue</button><button class="sm" onclick="smv(${r.id},'Adjusted')">Adjust to</button>`:''}</td></tr>`}).join('')||'<tr><td>No stock recorded yet</td></tr>'}</table></div><p class="mu">Inventory controls availability only. Prices, descriptions and banners are set by other departments.</p>`}
function smv(id,t){const q=+$('#sq').value;if(isNaN(q)||q<0)return toast('Enter a quantity');act(()=>api('/api/stock/'+id+'/move','POST',{type:t,qty:q}))}
V.grp=()=>{const d=S.me.dept,a=DB.msgs.map(m=>({...m,i:m.id})).filter(m=>m.dept==d),row=m=>`<div class="ms ${m.pin?'pn':''}">${m.pin?'📌 ':''}<b>${E(m.u)}</b> <small class="mu">${fm(m.ts)}</small><br>${E(m.t)}${S.me.type=='head'?` <button class="sm" onclick="pin(${m.i})">${m.pin?'Unpin':'Pin'}</button>`:''}</div>`;
return `<h2>${E(d)} Group</h2><p class="mu">Everyone in ${E(d)} is in this group automatically. Share files under Documents.</p>${a.filter(m=>m.pin).map(row).join('')}${a.filter(m=>!m.pin).map(row).join('')||'<p class="mu">No messages yet.</p>'}<textarea id="gm" rows="2" placeholder="${S.me.type=='head'?'Post an announcement or message':'Write a message'}"></textarea><div class="bt"><button class="pr" onclick="gpost()">Send</button></div>`};
V.proj=()=>{const u=S.me,a=DB.projects.map(p=>({...p,i:p.id})).filter(p=>p.dept==u.dept||isEx(u));return `<h2>Projects</h2>${u.type=='head'?`<div class="c"><h3>New project</h3><input id="pt" placeholder="Title"><textarea id="pd" rows="2" placeholder="Description"></textarea><input id="pdu" type="date"><select id="pp"><option>High</option><option selected>Medium</option><option>Low</option></select><div class="bt"><button class="pr" onclick="padd()">Publish to department</button></div></div>`:''}${a.map(p=>`<div class="c"><b>${E(p.title)}</b> <span class="pri">${p.pri}</span> <span class="pri">${p.status}</span><br>${E(p.desc)}<br><small class="mu">Due ${E(p.due||'—')}</small>${u.type=='head'&&p.status!='Done'?` <button class="sm" onclick="pdone(${p.i})">Mark completed</button>`:''}</div>`).join('')||'<p class="mu">No projects yet.</p>'}`};
V.task=()=>{const u=S.me,my=DB.tasks.filter(t=>t.to==u.email),hd=u.type=='head',ms=mem(u.dept);
const row=t=>`<div class="c"><b>${E(t.title)}</b> <span class="pri">${t.pri}</span><br><small class="mu">By ${E(t.by)} · Due ${E(t.due||'—')}</small><br>${t.to==u.email?`<select onchange="tst(${t.id},this.value)" style="width:auto">${['To do','In progress','Done'].map(s=>`<option ${t.status==s?'selected':''}>${s}</option>`).join('')}</select>`:`${E(t.to)} · <b>${t.status}</b>`}</div>`;
return `<h2>My Tasks</h2>${my.map(row).join('')||'<p class="mu">No tasks assigned to you.</p>'}${hd?`<h3>Assign a task</h3><div class="c"><input id="tt" placeholder="Task"><input id="tdu" type="date"><select id="tp"><option>High</option><option selected>Medium</option><option>Low</option></select><label><input type="checkbox" style="width:auto" onchange="document.querySelectorAll('.ta').forEach(c=>c.checked=this.checked)"> <b>All department members</b></label>${ms.map(m=>`<label style="display:block"><input class="ta" type="checkbox" style="width:auto" value="${E(m.email)}"> ${E(nm(m))} <small class="mu">${E(m.email)}</small></label>`).join('')}<div class="bt"><button class="pr" onclick="tadd()">Assign</button></div></div><h3>Department progress</h3>${DB.tasks.filter(t=>t.dept==u.dept&&t.to!=u.email).map(row).join('')||'<p class="mu">Nothing assigned yet.</p>'}`:''}`};
V.att=()=>{const u=S.me,r=DB.att.filter(a=>a.email==u.email).reverse();return `<h2>Attendance</h2>${u.type=='head'?`<div class="c"><h3>Department QR code (today)</h3><div id="qr" style="margin:10px 0"></div><p class="mu">Staff in ${E(u.dept)} scan this to sign in. It changes daily. Long-press or right-click the image to save it.</p><div class="bt"><button onclick="dlqr()">Download QR</button></div></div>`:''}<div class="bt"><button class="pr" onclick="scan()">Sign in</button></div><h3>My records</h3>${r.map(a=>`<div class="ms">${fm(a.ts)}</div>`).join('')||'<p class="mu">No sign-ins yet.</p>'}`};
V.atr=()=>`<h2>Attendance Records</h2><div class="tw"><table><tr><th>Staff</th><th>Dept</th><th>Signed in</th></tr>${[...DB.att].reverse().map(a=>{const u=DB.users.find(x=>x.email==a.email)||{};return `<tr><td>${E(nm(u.email?u:{email:a.email}))}</td><td>${E(u.dept)}</td><td>${fm(a.ts)}</td></tr>`}).join('')||'<tr><td>No records yet</td></tr>'}</table></div>`;
V.note=()=>`<h2>Notifications</h2>${DB.notes.filter(n=>n.to==S.me.email||n.to=='*').map(n=>`<div class="ms">${E(n.t)} <small class="mu">${fm(n.ts)}</small></div>`).join('')||'<p class="mu">You are all caught up.</p>'}`;
V.ann=()=>{const u=S.me;return `<h2>Announcement Board</h2>${isEx(u)||isHR(u)?`<div class="c"><input id="at" placeholder="Announcement to all departments"><div class="bt"><button class="pr" onclick="aadd()">Publish to everyone</button></div></div>`:''}${DB.ann.map(a=>`<div class="ms"><b>${E(a.t)}</b><br><small class="mu">${E(a.by)} · ${fm(a.ts)}</small></div>`).join('')||'<p class="mu">No announcements.</p>'}`};
const AF=[['name','Full name'],['phone','Phone number'],['nat','Nationality'],['soo','State of origin'],['dob','Date of birth','date'],['addr','Residential address'],['nn','Next of kin: name'],['np','Next of kin: phone'],['na','Next of kin: address']];
V.acct=()=>{const u=S.me;return `<h2>My Account</h2><div class="c"><label>Email<input value="${E(u.email)}" disabled></label><label>Department<input value="${E(u.dept)}" disabled></label><label>Position<input value="${E(u.pos)}" disabled></label><label>ID number<input value="${u.id}" disabled></label>${AF.map(f=>`<label>${f[1]}<input id="pf_${f[0]}" type="${f[2]||'text'}" value="${E(u.pf[f[0]])}"></label>`).join('')}<div class="ms" style="display:flex;justify-content:space-between;align-items:center"><b>Dark mode</b><button class="sm" type="button" onclick="theme(${document.documentElement.dataset.theme!='dark'})">${document.documentElement.dataset.theme=='dark'?'On':'Off'}</button></div><div class="bt"><button class="pr" onclick="asave()">Save</button></div></div>`};
const pwf=(id,ph,x)=>`<div class="pw"><input id="${id}" type="password" placeholder="${ph}" ${x||''}><button type="button" class="eye" onclick="eye('${id}',this)" aria-label="Show or hide">👁</button></div>`;
function eye(id,b){const i=$('#'+id);i.type=i.type=='password'?'text':'password';b.textContent=i.type=='password'?'👁':'🙈'}
function theme(d){document.documentElement.dataset.theme=d?'dark':'light';try{localStorage.setItem('gp_theme',d?'dark':'light')}catch(e){}render()}
const rd=()=>({email:$('#fe').value.trim().toLowerCase(),dept:$('#fd').value,pos:$('#fp').value.trim(),type:$('#ft').value,code:$('#fk')?$('#fk').value.trim():''});
function mailto(u){const b=`GRACELLE HUMAN RESOURCES & ADMINISTRATION\n\nSUBJECT: STAFF PORTAL ACCESS GRANTED\n\nDear Staff Member,\n\nWelcome on board!\n\nWe are pleased to inform you that your access to the GRACELLE Administrative Forum Group has been successfully approved and activated.\n\nAs a registered member of the organisation, you have been issued a unique access code which grants you entry into your designated Staff Portal.\n\n${u.type=='head'?'YOUR STAFF ACCESS CODE: '+u.code+'\nYOUR STAFF ID NUMBER: '+u.id:'YOUR STAFF ID NUMBER: '+u.id}\n\nThis code serves as your personal authentication credential for accessing the staff portal and other authorised internal administrative platforms.\n\nIMPORTANT SECURITY & ACCESS GUIDELINES\n1. Your access code is strictly personal and must not be shared, transferred, or disclosed to another individual.\n2. Staff members are expected to comply with all organisational policies, administrative guidelines, and internal communication protocols.\n3. Your access code should be kept confidential at all times. In the event of a lost or compromised code, kindly contact the Human Resources Department for assistance.\n4. Access codes may be retrieved, reset, suspended, or revoked by the HR/Administrative Department where necessary.\n5. In the event of resignation, termination of appointment, dismissal, or any other form of disengagement from the organisation, your portal access and associated credentials may be withdrawn immediately.\n6. Unauthorised access, misuse of company resources, or disclosure of confidential organisational information may attract appropriate disciplinary action.\n\nPlease ensure that you familiarise yourself with the staff portal and all applicable organisational guidelines.\n\nOnce again, welcome to the team. We look forward to your commitment, professionalism, and valuable contributions to the organisation.\n\nGRACE IN EVERY STYLE.\nHuman Resources & Administration\nGracelle`;return 'mailto:'+encodeURIComponent(u.email)+'?subject='+encodeURIComponent('STAFF PORTAL ACCESS GRANTED')+'&body='+encodeURIComponent(b)}
V.acs=()=>{const d=S.dr,s=S.sent,hr=isHR(S.me);return `<h2>Staff &amp; Access</h2>${hr?`<div class="c"><h3>Register staff / generate access</h3><input id="fe" type="email" placeholder="Staff Gmail (as provided by them)" value="${E(d&&d.email)}"><select id="fd">${DEPTS.map(x=>`<option ${d&&d.dept==x?'selected':''}>${E(x)}</option>`).join('')}</select><input id="fp" placeholder="Position (type manually)" value="${E(d&&d.pos)}"><select id="ft" onchange="S.dr=rd();render()"><option value="head" ${d&&d.type=='staff'?'':'selected'}>Administrator / official (access code + ID)</option><option value="staff" ${d&&d.type=='staff'?'selected':''}>Regular staff (ID only)</option></select>${d&&d.type=='staff'?'':`${pwf('fk','Access key combination (type manually)','value="'+E(d&&d.code)+'"')}`}<div class="bt"><button onclick="hsave()">Save</button>${d&&d.ok?'<button class="pr" onclick="grant()">GRANT ACCESS</button>':''}</div>${s?`<div class="ok">Access granted. ID number: <b>${s.u.id}</b><br>${s.mail&&s.mail.sent?'Email sent automatically to '+E(s.u.email)+'.':E((s.mail&&s.mail.reason)||'Press Send to email the details.')}<div class="bt"><button class="pr" onclick="resend('${s.u.id}')">Send to ${E(s.u.email)}</button><a class="btn" href="${mailto({...s.u,code:s.code})}" target="_blank">Open in my email app</a></div></div>`:''}</div>`:''}
<h3>Staff directory (${DB.users.length})</h3><div class="tw"><table><tr><th>ID</th><th>Email</th><th>Department</th><th>Position</th><th>Type</th><th>Status</th><th></th></tr>${DB.users.map(u=>`<tr><td>${u.id}</td><td>${E(u.email)}</td><td>${E(u.dept)}</td><td>${E(u.pos)}</td><td>${u.type=='head'?'Access code':'Staff'}</td><td>${u.status}</td><td><button class="sm" onclick="view('${u.id}')">View</button>${hr?`${u.type=='head'?`<button class="sm" onclick="setcode('${u.id}')">Change code</button>`:''}<button class="sm" onclick="susp('${u.id}')">${u.status=='Active'?'Suspend':'Activate'}</button>${u.id!=S.me.id?`<button class="sm d" onclick="del('${u.id}')">${S.cd==u.id?'Sure?':'Delete'}</button>`:''}`:''}</td></tr>`).join('')}</table></div>`};
function title(t){return t=='dept'?'Department':(LB[t]||(C[t]&&C[t].t)||({dash:'Dashboard',grp:'Department Group',proj:'Projects',task:'My Tasks',att:'Attendance',note:'Notifications',ann:'Announcements',acct:'My Account'}[t])||t)}
function render(){const a=$('#app'),u=S.me;if(!u){a.innerHTML=`<div class="lg"><img src="logo.png" alt="GRACELLE"><h2>Staff Portal</h2><p class="mu">Log in with your email and your access code (officials) or ID number (staff).</p>${S.lm?`<p class="err">${E(S.lm)}</p>`:''}<input id="le" type="email" placeholder="Email">${pwf('lk','Access code or ID number','onkeydown="if(event.key==\'Enter\')login()"')}<div class="bt"><button class="pr" style="width:100%" onclick="login()">Log in</button></div><p class="mu" style="font-size:13px">Staff only. Access is issued by HR.</p></div>`;return}
const dm=(MENU[mk(u)]||[]).map(it).filter(x=>x[0]!='acs'||u.dept=='HR'||isEx(u)),ws=[['grp','Department Group'],['proj','Projects'],['task','My Tasks'],['att','Attendance'],['leave','Leave Requests'],['rpt','Reports'],['doc','Documents']].concat(u.dept=='HR'?[]:[['perf','Performance']],[['note','Notifications'],['ann','Announcements'],['rem','Reminders'],['acct','My Account']]),ln=x=>`<a class="${S.tab==x[0]?'on':''}" onclick="go('${x[0]}')">${E(x[1])}</a>`;
a.innerHTML=`<div class="sh"><div class="shade ${S.so?'on':''}" onclick="S.so=false;render()"></div><aside class="${S.so?'on':''}"><button class="x" onclick="S.so=false;render()" aria-label="Close menu">✕</button><div class="br"><img src="logo.png" alt="">STAFF PORTAL</div>${ln(['dash','Dashboard'])}<div class="sl">${E(isEx(u)?'EXECUTIVE':u.dept.toUpperCase())}</div>${dm.map(ln).join('')}<div class="sl">MY WORKSPACE</div>${ws.map(ln).join('')}<a onclick="logout()">Log out</a></aside><div class="mn"><div class="tp"><button class="mb" onclick="S.so=!S.so;render()" aria-label="Menu">☰</button><b>${E(title(S.tab))}</b><span class="mu">${E(nm(u))}</span><button class="sm" onclick="go('acct')" aria-label="My Account">👤</button></div><div class="ct">${S.tab=='dash'?'':'<button class="sm" style="margin-bottom:10px;padding:8px 14px" onclick="back()">← Back</button>'}${(V[S.tab]||(()=>colv(S.tab)))(S.arg)}</div></div></div>`;
if(S.tab=='att'&&u.type=='head'&&window.QRCode){const q=$('#qr');q.innerHTML='';new QRCode(q,{text:'GRCATT:'+u.dept+':'+T(),width:200,height:200})}}
function back(){const x=S.h.pop()||['dash'];S.nb=1;go(x[0],x[1]);S.nb=0}
function go(t,a){if(!S.nb&&(S.tab!=t||S.arg!==a))S.h.push([S.tab,S.arg]);S.tab=t;S.arg=a;S.so=false;S.cd=null;render();scrollTo(0,0)}
async function login(){const e=$('#le').value.trim().toLowerCase(),k=$('#lk').value.trim();try{const d=await api('/api/staff/login','POST',{email:e,key:k});TOK=d.token;S.me=d.me;S.lm='';S.h=[];last=Date.now();S.tab='dash';await pull();render()}catch(x){S.lm=x.message||'Login failed';render()}}
function logout(m){stopCam();TOK=null;S.me=null;S.h=[];S.lm=m||'';closeM();DB.rec={};render()}
function hsave(){const d=rd();if(!/^\S+@\S+\.\S+$/.test(d.email))return toast('Enter a valid email');if(!d.pos)return toast('Enter the position');if(d.type=='head'&&d.code.length<6)return toast('Enter an access key (6+ characters)');if(DB.users.some(u=>u.email==d.email))return toast('This email is already registered');d.ok=1;S.dr=d;S.sent=null;toast('Saved. Now grant access.');render()}
async function grant(){const d=S.dr;try{const r=await api('/api/hr/users','POST',{email:d.email,dept:d.dept,pos:d.pos,type:d.type,code:d.code});S.sent={u:r.user,code:d.code,mail:r.mail};S.dr=null;await pull();render()}catch(e){toast(e.message)}}
async function resend(id){try{const r=await api('/api/hr/users/'+id+'/send','POST',{code:(S.sent&&S.sent.code)||''});S.sent.mail=r.mail;render();toast(r.mail.sent?'Email sent':r.mail.reason)}catch(e){toast(e.message)}}
function susp(id){const u=DB.users.find(x=>x.id==id);if(u.id==S.me.id)return toast('You cannot suspend yourself');act(()=>api('/api/hr/users/'+id,'PATCH',{status:u.status=='Active'?'Suspended':'Active'}))}
function del(id){if(S.cd!=id){S.cd=id;return render()}S.cd=null;act(()=>api('/api/hr/users/'+id,'DELETE'))}
function setcode(id){modal(`<h3>Change access code</h3>${pwf('nc','New access key (type manually)')}<div class="bt"><button class="pr" onclick="setc2('${id}')">Save</button><button onclick="closeM()">Cancel</button></div>`)}
async function setc2(id){const cd=$('#nc').value.trim();if(cd.length<6)return toast('6+ characters');try{await api('/api/hr/users/'+id,'PATCH',{code:cd});const u=DB.users.find(x=>x.id==id);closeM();S.sent={u,code:cd,mail:null};await pull();render();toast('Changed. Press Send to email the new code.')}catch(e){toast(e.message)}}
function view(id){const u=DB.users.find(x=>x.id==id);modal(`<h3>${E(nm(u))}</h3><p>${u.id} · ${E(u.email)}<br>${E(u.dept)} · ${E(u.pos)}</p>${AF.map(f=>`<div class="ms"><small class="mu">${f[1]}</small><br>${E((u.pf||{})[f[0]])||'—'}</div>`).join('')}<div class="bt"><button onclick="closeM()">Close</button></div>`)}
function asave(){const b={};AF.forEach(f=>b[f[0]]=$('#pf_'+f[0]).value.trim());act(()=>api('/api/staff/profile','PUT',b),'Saved. HR can now see your details.')}
function gpost(){const t=$('#gm').value.trim();if(!t)return;act(()=>api('/api/msgs','POST',{t}))}
function pin(i){act(()=>api('/api/msgs/'+i+'/pin','PATCH',{}))}
function padd(){const t=$('#pt').value.trim();if(!t)return toast('Add a title');act(()=>api('/api/projects','POST',{title:t,desc:$('#pd').value.trim(),due:$('#pdu').value,pri:$('#pp').value}))}
function pdone(i){act(()=>api('/api/projects/'+i,'PATCH',{}))}
function tadd(){const t=$('#tt').value.trim(),to=[...document.querySelectorAll('.ta:checked')].map(x=>x.value);if(!t)return toast('Add the task');if(!to.length)return toast('Select who it is for');act(()=>api('/api/tasks','POST',{title:t,pri:$('#tp').value,due:$('#tdu').value,to}),'Assigned to '+to.length)}
function tst(id,v){act(()=>api('/api/tasks/'+id,'PATCH',{status:v}))}
function aadd(){const t=$('#at').value.trim();if(!t)return;act(()=>api('/api/announcements','POST',{t}),'Published')}
function dlqr(){const q=$('#qr canvas');if(!q)return;const a=document.createElement('a');a.href=q.toDataURL('image/png');a.download='attendance-qr-'+T()+'.png';a.click()}
let cam=null;
async function scan(){modal(`<h3>Scan attendance QR</h3><div style="position:relative"><video id="cv" playsinline muted style="width:100%;border-radius:12px;background:#000;min-height:240px"></video><div class="fr"></div></div><canvas id="cs" hidden></canvas><p class="mu" id="sm">Looking for a QR code…</p><input id="mq" placeholder="Camera blocked? Paste the QR code text"><div class="bt"><button class="pr" onclick="sign($('#mq').value.trim())">Sign in with text</button><button onclick="closeM()">Cancel</button></div>`);
try{cam=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const v=$('#cv');v.srcObject=cam;await v.play();const cv=$('#cs'),x=cv.getContext('2d',{willReadFrequently:true});const lp=()=>{if(!cam)return;if(v.videoWidth){cv.width=v.videoWidth;cv.height=v.videoHeight;x.drawImage(v,0,0);const r=window.jsQR&&jsQR(x.getImageData(0,0,cv.width,cv.height).data,cv.width,cv.height);if(r&&r.data){const s=$('#sm');if(sign(r.data))return;if(s)s.textContent='QR found, but it is not your department\'s code for today. Keep looking…'}}requestAnimationFrame(lp)};lp()}catch(e){const s=$('#sm');if(s)s.textContent='Camera unavailable here. Paste the code text below.'}}
function stopCam(){if(cam){cam.getTracks().forEach(t=>t.stop());cam=null}}
function sign(txt){if(txt!='GRCATT:'+S.me.dept+':'+T())return false;closeM();api('/api/attendance/sign','POST',{code:txt}).then(()=>pull()).then(()=>{render();toast('Signed in. Have a great day!')}).catch(e=>toast(e.message));return true}
let last=Date.now();['click','keydown','touchstart','mousemove'].forEach(e=>addEventListener(e,()=>last=Date.now(),{passive:true}));
function chk(){if(S.me&&Date.now()-last>6e5)logout('You were logged out after 10 minutes of inactivity. Please log in again.')}
setInterval(chk,10000);document.addEventListener('visibilitychange',chk);
setInterval(()=>{if(!S.me)return;const now=Date.now();R('rem').filter(r=>r.by==S.me.email&&!r.fired&&r.v.at&&new Date(r.v.at)<=now).forEach(r=>{r.fired=1;toast('Reminder: '+r.v.what);try{if(Notification.permission=='granted')new Notification('GRACELLE reminder',{body:r.v.what})}catch(e){}api('/api/rec/rem/'+r.id,'PATCH',{fired:1}).catch(()=>{})})},20000);
setInterval(()=>{if(S.me&&!(document.activeElement&&/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)))pull().then(render).catch(()=>{})},60000);
render();
